"""Hand-built, re-sealed contradictions; not generated by the runtime producer."""
from copy import deepcopy
from pathlib import Path
import tempfile
import unittest

import reconstruct as b
import runtime_reconstruct as r


def write(path,value):
    raw=b.canonical(value)+b'\n';path.write_bytes(raw)
    return {'sha256':b.sha(raw),'bytes':len(raw)}


class RuntimeArtifactTests(unittest.TestCase):
    def setUp(self):
        base=Path(__file__).resolve().parents[4]/'data/cache/inspect-runtime-independent-tests';base.mkdir(parents=True,exist_ok=True)
        self.temp=tempfile.TemporaryDirectory(dir=base);self.addCleanup(self.temp.cleanup)
        self.root=Path(self.temp.name);self.source=self.root/'source';self.source.mkdir();self.record=self.root/'record';self.record.mkdir()
        raw_pin=write(self.source/'raw.json',{'value':'invented'})
        obs={'observation_id':'obs-1','status':'observed','category':'genetics','target_id':'target',
             'indication_id':'disease','program_id':None,'statement':'invented original','input_refs':['raw-1']}
        self.grounded={'observation':obs,'citation':{'artifact_id':'packet-1','dataset_id':'fixture','release_id':'v1','source_url':'https://example.invalid/fixture','artifact_sha256':''}}
        packet_pin=write(self.source/'evidence.json',{'schema_version':2,'observations':[obs]})
        self.grounded['citation']['artifact_sha256']=packet_pin['sha256']
        artifact={'artifact_id':'packet-1','dataset_id':'fixture','release_id':'v1','source_url':'https://example.invalid/fixture',
                  'path':'evidence.json','sha256':packet_pin['sha256'],'input_refs':['raw-1']}
        node={'source_id':'raw-1','dataset_id':'fixture','release_id':'v1','path':'raw.json','sha256':raw_pin['sha256'],
              'parents':[],'receipt_path':None,'receipt_sha256':None}
        case={'case_id':'fiction','hypothesis':{'target_id':'target','indication_id':'disease'},'program':None}
        snapshot={'artifacts':[artifact],'sources':[node],'raw_root':None}
        write(self.source/'case.json',case);write(self.source/'snapshot.json',snapshot)
        descriptor={'control_id':'IX-test','paths':{'case':'case.json','snapshot':'snapshot.json'}}
        descriptor_pin=write(self.source/'descriptor.json',descriptor)
        self.context={'case':case,'snapshot':snapshot,'descriptor_sha256':descriptor_pin['sha256'],'scorer_sha256':b.fingerprint(None),
            'admitted_fingerprints':{'obs-1':b.fingerprint(self.grounded)},
            'source_proofs':[{'artifact_id':'packet-1','path':str(self.source/'evidence.json'),'sha256':packet_pin['sha256']},
                             {'artifact_id':'raw-1','path':str(self.source/'raw.json'),'sha256':raw_pin['sha256']}],
            'exclusions':[],'scorer_preflight':None}
        context_pin=write(self.record/'context.json',self.context)
        budget={'max_calls':2,'max_input_tokens':200,'max_output_tokens':200,'max_cost_usd':0.0,'max_seconds':30.0}
        self.content='{"observation_ids":["obs-1"]}'
        self.row={'id':'IX-test','input':{'control_id':'IX-test','bundle_root':str(self.source),'descriptor':{'path':'descriptor.json',**descriptor_pin}},
                  'budget':budget,'steps':[{'category':'genetics','script':{'content':self.content}}]}
        self.request={'case_id':'fiction','category':'genetics','step':0,'context_sha256':b.fingerprint(self.context),'offered_observation_ids':['obs-1']}
        quote={'input_tokens':20,'output_tokens':40,'cost_usd':0.0};actual={'input_tokens':10,'output_tokens':8,'cost_usd':0.0};zero={'input_tokens':0,'output_tokens':0,'cost_usd':0.0}
        identity={'control_id':'IX-test','attempt':0,'epoch':1,'native_sample_uuid':'sample-uuid','run_id':'run','eval_id':'eval','task_name':'task'}
        native_usage={'input_tokens':10,'output_tokens':8,'total_tokens':18,'total_cost':0.0}
        self.response={'completion':self.content,'choices':[{'message':{'content':self.content,'role':'assistant'}}],'usage':native_usage}
        response_pin=write(self.record/'response-000.json',self.response)
        claim={'claim_id':'claim-'+b.fingerprint({'case':'fiction','evidence':self.grounded})[:20],'evidence':deepcopy(self.grounded),
               'admitted_fingerprint':b.fingerprint(self.grounded),'specialist':'genetics','extraction_mode':'verbatim_source_selection'}
        payload={'messages':[{'role':'user','content':b.canonical(self.request).decode()}],'tools':[],
            'configuration':{'temperature':0.0,'max_retries':0,'cache':False,'max_connections':1,'adaptive_connections':False,'max_tokens':40}}
        self.events=[{'event':'source_admitted','details':{'context':context_pin,'context_sha256':b.fingerprint(self.context)}},
            {'event':'attempt_reserved','details':{'attempt':0,'request':self.request,'request_sha256':b.fingerprint(self.request),'quote':quote}},
            {'event':'inspect_before_model','details':{'identity':identity}},
            {'event':'provider_entered','details':{'attempt':0,'entry':1}},
            {'event':'provider_dispatched','details':{'attempt':0,'request_sha256':b.fingerprint(self.request),'payload':payload,'payload_sha256':b.fingerprint(payload)}},
            {'event':'inspect_model_usage','details':{'identity':identity,'usage':native_usage,'retries':0}},
            {'event':'native_response','details':{'attempt':0,'response':response_pin}},
            {'event':'attempt_accounted','details':{'attempt':0,'request_sha256':b.fingerprint(self.request),'kind':'measured','usage':actual,'outcome':'completed','quote_breach':False,'response_sha256':response_pin['sha256']}},
            {'event':'claim_committed','details':claim}]
        self.result={'schema_version':1,'control_id':'IX-test','status':'completed','error':None,
            'accounting':{'calls':1,'measured_usage':actual,'estimated_usage':zero,'usage':actual,'outstanding_reservation':zero,'conservative_upper_usage':actual,'unresolved_calls':0},
            'provider_entries':1,'provider_dispatches':1,'context_sha256':b.fingerprint(self.context),'last_response_content':self.content,
            'commits':[{'claims':[claim],'reviewed_ids':['obs-1'],'status':'completed','prediction':{'probability':None}}]}
        self.native={'id':'IX-test','epoch':1,'uuid':'sample-uuid','input':b.canonical(self.row['input']).decode(),'target':'',
            'error_retries':[],'output':deepcopy(self.response),'model_usage':{'fixture':native_usage},
            'events':[{'event':'model','output':deepcopy(self.response),'model':'fixture','config':payload['configuration']} ]}
        self.header={'eval':{'run_id':'run','eval_id':'eval','task':'task'}}

    def seal(self,terminal=True):
        request_pin=write(self.record/'request.json',self.row);result_pin=write(self.record/'result.json',self.result)
        events=[{'event':'reserved','details':{'request_sha256':b.fingerprint(self.row)}},*self.events]
        if terminal:events.append({'event':'terminal','details':{'result':result_pin}})
        previous='0'*64;serialized=[]
        for number,event in enumerate(events):
            row={**event,'sequence':number,'previous_sha256':previous,'at_utc':'2026-01-01T00:00:00+00:00'}
            row['sha256']=b.fingerprint(row);previous=row['sha256'];serialized.append(b.canonical(row)+b'\n')
        journal=b''.join(serialized);(self.record/'journal.jsonl').write_bytes(journal)
        return write(self.record/'receipt.json',{'schema_version':1,'kind':'inspect_policy_case','request':request_pin,'result':result_pin,
            'journal':{'sha256':b.sha(journal),'bytes':len(journal)},'terminal_chain_sha256':previous})['sha256']

    def audit(self,terminal=True):
        return r.runtime_record(self.row,self.record,self.seal(terminal),self.native,native_header=self.header)

    def test_handbuilt_complete_source_and_native_join(self):
        self.assertEqual(self.audit()['sources']['claims_joined'],1)

    def test_changed_original_source_and_omitted_parent_proof_reject(self):
        (self.source/'raw.json').write_text('{"changed":true}')
        with self.assertRaises(ValueError):self.audit()
        self.setUp();self.context['source_proofs'].pop()
        self.events[0]['details']['context']=write(self.record/'context.json',self.context)
        self.events[0]['details']['context_sha256']=b.fingerprint(self.context)
        self.result['context_sha256']=b.fingerprint(self.context)
        with self.assertRaises(ValueError):self.audit()

    def test_reattached_fabricated_claim_rejects(self):
        claim=self.result['commits'][0]['claims'][0]
        claim['evidence']['observation']['statement']='changed claim'
        claim['admitted_fingerprint']=b.fingerprint(claim['evidence'])
        claim['claim_id']='claim-'+b.fingerprint({'case':'fiction','evidence':claim['evidence']})[:20]
        with self.assertRaises(ValueError):self.audit()

    def test_resealed_response_and_native_text_cannot_change_selection(self):
        replacement='{"observation_ids":["other"]}'
        self.response['completion']=replacement;self.response['choices'][0]['message']['content']=replacement
        pin=write(self.record/'response-000.json',self.response)
        self.events[6]['details']['response']=pin;self.events[7]['details']['response_sha256']=pin['sha256']
        self.native['output']=deepcopy(self.response);self.native['events'][0]['output']=deepcopy(self.response)
        self.result['last_response_content']=replacement
        with self.assertRaises(ValueError):self.audit()

    def test_inflated_native_usage_rejects(self):
        self.native['model_usage']=deepcopy(self.native['model_usage']);self.native['model_usage']['fixture']['input_tokens']=999
        with self.assertRaises(ValueError):self.audit()

    def test_wrong_callback_run_identity_rejects(self):
        self.events[2]['details']['identity']['run_id']='other-run'
        with self.assertRaises(ValueError):self.audit()

    def test_wrong_response_accounting_pin_and_hook_usage_reject(self):
        self.events[7]['details']['response_sha256']='f'*64
        with self.assertRaises(ValueError):self.audit()
        self.setUp();self.events[5]['details']['usage']=deepcopy(self.events[5]['details']['usage'])
        self.events[5]['details']['usage']['output_tokens']=900
        with self.assertRaises(ValueError):self.audit()

    def test_missing_terminal_rejects_even_with_resealed_bytes(self):
        with self.assertRaises(ValueError):self.audit(terminal=False)


if __name__=='__main__':unittest.main()
